remote() {
  local host="$1"; shift
  case ",${ALLOWED_HOSTS}," in
    *",${host},"*) ;;
    *)
      echo "Refusing remote operation on non-allowed host: ${host}" >&2
      return 99
      ;;
  esac
  sshpass -p "${SSH_PASS}" ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile="${KNOWN}" "${SSH_USER}@${host}" "$@"
}

iface_for_host() {
  local host="$1" item
  IFS=',' read -r -a _iface_items <<<"${HOST_IFACE_OVERRIDES}"
  for item in "${_iface_items[@]}"; do
    if [[ "${item}" == "${host}="* ]]; then
      echo "${item#*=}"
      return 0
    fi
  done
  echo "${IFACE}"
}

record() {
  local stage="$1" status="$2" note="$3"
  printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$(date -u +%FT%TZ)" "${stage}" "${SCHEME}" "${status}" "http://${DECODE_HEAD}:${PROXY_PORT}/v1" "${PREFILL0_HEAD},${PREFILL0_WORKER};${PREFILL1_HEAD},${PREFILL1_WORKER}" "${DECODE_HEAD},${DECODE_WORKER}" "${note}" >> "${TASK_ROOT}/state/deployment.tsv"
}

