ensure_container() {
  local host="$1" name="$2"
  local host_iface
  host_iface="$(iface_for_host "${host}")"
  remote "${host}" "bash -lc '
set -euo pipefail
desired_image_id=\"\$(docker image inspect \"${IMAGE}\" --format \"{{.Id}}\")\"
if docker ps -a --format \"{{.Names}}\" | grep -Fxq \"${name}\"; then
  current_image_id=\"\$(docker inspect \"${name}\" --format \"{{.Image}}\")\"
  if [[ \"\${current_image_id}\" != \"\${desired_image_id}\" ]]; then
    docker rm -f \"${name}\" >/dev/null
  fi
fi
if ! docker ps -a --format \"{{.Names}}\" | grep -Fxq \"${name}\"; then
  docker run -d --name \"${name}\" --gpus all --privileged --net=host --ipc=host --pid=host --shm-size=64g \
    --ulimit memlock=-1:-1 --ulimit stack=67108864 \
    -e NVIDIA_DRIVER_CAPABILITIES=all \
    -e NCCL_SOCKET_IFNAME=${host_iface} -e NCCL_IB_HCA=${NCCL_IB_HCA} -e GLOO_SOCKET_IFNAME=${host_iface} \
    -e UCX_TLS=${UCX_TLS} -e UCX_DEVICES=${UCX_DEVICES} -e UCX_NET_DEVICES=${UCX_NET_DEVICES} \
    -e UCX_MAX_RNDV_RAILS=${UCX_MAX_RNDV_RAILS} -e UCX_MAX_EAGER_RAILS=${UCX_MAX_EAGER_RAILS} -e UCX_CM_USE_ALL_DEVICES=${UCX_CM_USE_ALL_DEVICES} \
    --device /dev/infiniband \
    -v /nfs:/nfs -v ${BASE}:/workspace \
    --entrypoint /bin/sleep ${IMAGE} infinity >/dev/null
fi
if ! docker ps --format \"{{.Names}}\" | grep -Fxq \"${name}\"; then docker start \"${name}\" >/dev/null; fi
'"
}

