printf '%s\n' "\${SUDO_PASS}" | sudo -S pkill -KILL -f '[v]llm.entrypoints.cli.main serve ${MODEL_PATH}' >/dev/null 2>&1 || true
printf '%s\n' "\${SUDO_PASS}" | sudo -S pkill -KILL -f '[t]oy_proxy_server.py' >/dev/null 2>&1 || true
