wait_gpu_memory_released() {
  local host="$1" label="${2:-task}"
  local threshold="${GPU_MEMORY_SETTLE_USED_MIB}"
  local timeout_sec="${GPU_MEMORY_SETTLE_TIMEOUT_SEC}"
  local interval_sec="${GPU_MEMORY_SETTLE_INTERVAL_SEC}"
  local deadline=$((SECONDS + timeout_sec))
  local max_used log_file
  log_file="${LOG_DIR}/${TS}_gpu_memory_settle.log"
  while ((SECONDS < deadline)); do
    max_used="$(
      remote "${host}" "bash -lc 'nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits 2>/dev/null | tr -cd \"0-9\n\" | sort -nr | head -n1 || true'" 2>/dev/null || echo 0
    )"
    max_used="${max_used//$'\r'/}"
    max_used="${max_used//$'\n'/}"
    [[ -n "${max_used}" ]] || max_used=0
    printf '%s\thost=%s\tlabel=%s\tmax_used_mib=%s\tthreshold_mib=%s\n' \
      "$(date -u +%FT%TZ)" "${host}" "${label}" "${max_used}" "${threshold}" >> "${log_file}"
    if ((max_used <= threshold)); then
      return 0
    fi
    sleep "${interval_sec}"
  done
  echo "GPU memory on ${host} did not settle below ${threshold} MiB for ${label}; latest max_used_mib=${max_used}" >&2
  return 1
}

wait_all_task_gpu_memory_released() {
  local label="${1:-task}"
  wait_gpu_memory_released "${PREFILL0_HEAD}" "${label}:prefill_p0_head"
  wait_gpu_memory_released "${PREFILL0_WORKER}" "${label}:prefill_p0_worker"
  wait_gpu_memory_released "${PREFILL1_HEAD}" "${label}:prefill_p1_head"
  wait_gpu_memory_released "${PREFILL1_WORKER}" "${label}:prefill_p1_worker"
  wait_gpu_memory_released "${DECODE_HEAD}" "${label}:decode_head"
  wait_gpu_memory_released "${DECODE_WORKER}" "${label}:decode_worker"
}

