restart_container_clean() {
  local host="$1" name="$2"
  remote "${host}" "timeout 90s docker restart ${name} >/dev/null || true"
  remote "${host}" "
for i in \$(seq 1 24); do
  if docker exec '${name}' python3 -c 'import torch; torch.cuda.init(); assert torch.cuda.device_count() > 0' >/dev/null 2>&1; then
    exit 0
  fi
  sleep 5
done
echo 'CUDA preflight failed after docker restart for ${name}' >&2
docker exec '${name}' nvidia-smi -L >&2 || true
exit 1
"
}

cuda_preflight_container() {
  local host="$1" name="$2"
  remote "${host}" "docker exec '${name}' python3 -c \"import torch; torch.cuda.init(); assert torch.cuda.device_count() > 0\""
}

cleanup_role_start_residue() {
  local host="$1" name="$2" role="$3" rank="$4"
  local service_port="" master_port=""
  [[ "${role}" == "proxy" ]] && return 0

  stop_task_processes "${host}" "${name}"
  [[ "${rank}" == "0" ]] || return 0

  case "${role}" in
    prefill)
      service_port="${PREFILL_PORT}"
      master_port="${PREFILL_MASTER_PORT}"
      ;;
    decode|nonpd)
      service_port="${DECODE_PORT}"
      master_port="${DECODE_MASTER_PORT}"
      ;;
    *)
      return 0
      ;;
  esac

  remote "${host}" "SUDO_PASS=$(printf '%q' "${SSH_PASS}") SERVICE_PORT=${service_port} MASTER_PORT=${master_port} bash -s" <<'REMOTE'
set -euo pipefail
for p in "${SERVICE_PORT}" "${MASTER_PORT}"; do
  if ss -H -ltn "sport = :${p}" | grep -q .; then
    if command -v fuser >/dev/null 2>&1; then
      printf '%s\n' "${SUDO_PASS}" | sudo -S fuser -k -TERM "${p}/tcp" >/dev/null 2>&1 || true
      sleep 2
    fi
  fi
  if ss -H -ltn "sport = :${p}" | grep -q .; then
    if command -v fuser >/dev/null 2>&1; then
      printf '%s\n' "${SUDO_PASS}" | sudo -S fuser -k -KILL "${p}/tcp" >/dev/null 2>&1 || true
      sleep 2
    fi
  fi
  for _ in $(seq 1 30); do
    if ! ss -H -ltn "sport = :${p}" | grep -q .; then
      break
    fi
    sleep 1
  done
  if ss -H -ltn "sport = :${p}" | grep -q .; then
    echo "port ${p} is still busy before role start" >&2
    exit 1
  fi
done
REMOTE
}

