task_src_nfs=${TASK_ROOT}/source/vllm_glm52_v1/tests/v1/kv_connector/nixl_integration/toy_proxy_server.py
runtime_src=\${RUNTIME_PATCH_SOURCE_DIR}/tests/v1/kv_connector/nixl_integration/toy_proxy_server.py
src=\${task_src}
if [[ -f \"\${task_src_nfs}\" ]]; then
  src=\${task_src_nfs}
elif [[ -f \"\${runtime_src}\" ]]; then
  src=\${runtime_src}
fi
dst=/opt/vllm_glm52_v1/tests/v1/kv_connector/nixl_integration/toy_proxy_server.py
if [[ -f \"\${src}\" ]]; then
