stop_non_task_gpu_containers_if_needed() {
  local host="$1"
  local snapshot="${LOG_DIR}/${TS}_${host}_preexisting_containers.txt"
  remote "${host}" "docker ps --format '{{.Names}}'" > "${snapshot}" || true
  while IFS= read -r c; do
    [[ -z "${c}" ]] && continue
    case "${c}" in
      node-exporter|dcgm-exporter)
        continue
        ;;
      "${PREFILL_HEAD_CONTAINER}"|"${PREFILL_WORKER_CONTAINER}"|"${PREFILL1_HEAD_CONTAINER}"|"${PREFILL1_WORKER_CONTAINER}"|"${DECODE_HEAD_CONTAINER}"|"${DECODE_WORKER_CONTAINER}")
        continue
        ;;
      glm52_v2_stable_"${DEPLOY_LABEL}"_*|fp8_v7_tpot_*|fp8_v7_tpot_bench_*)
        echo "$(date -u +%FT%TZ) stopping prior task container ${c} on ${host}" >> "${LOG_DIR}/${TS}_exclusive_cleanup.log"
        remote "${host}" "docker stop ${c} >/dev/null || true"
        ;;
      *)
        echo "$(date -u +%FT%TZ) observed non-task container ${c} on ${host}; leave running unless STOP_NON_TASK_CONTAINERS=1" >> "${LOG_DIR}/${TS}_exclusive_cleanup.log"
        if [[ "${STOP_NON_TASK_CONTAINERS:-0}" == "1" ]]; then
          echo "$(date -u +%FT%TZ) stopping ${c} on ${host} because STOP_NON_TASK_CONTAINERS=1" >> "${LOG_DIR}/${TS}_exclusive_cleanup.log"
          remote "${host}" "docker stop ${c} >/dev/null || true"
        fi
        ;;
    esac
  done < "${snapshot}"
}

start_role() {
  local host="$1" container="$2" role="$3" rank="$4"
  local role_iface
  role_iface="$(iface_for_host "${host}")"
  local role_safetensors_load_strategy="${SAFETENSORS_LOAD_STRATEGY}"
  local role_tp_size="${ROLE_TP_SIZE:-}"
  local role_pp_size="${ROLE_PP_SIZE:-}"
  local role_layer_partition="${ROLE_LAYER_PARTITION:-}"
  local role_pp_max_concurrent_batches="${VLLM_PP_MAX_CONCURRENT_BATCHES}"
  case "${role}" in
    prefill)
      role_safetensors_load_strategy="${PREFILL_SAFETENSORS_LOAD_STRATEGY}"
      role_pp_max_concurrent_batches="${PREFILL_VLLM_PP_MAX_CONCURRENT_BATCHES}"
      ;;
    decode|nonpd)
      role_safetensors_load_strategy="${DECODE_SAFETENSORS_LOAD_STRATEGY}"
      role_pp_max_concurrent_batches="${DECODE_VLLM_PP_MAX_CONCURRENT_BATCHES}"
