  esac
  case "${role}" in
    prefill)
      role_tp_size="${PREFILL_ROLE_TP_SIZE:-${role_tp_size}}"
      role_pp_size="${PREFILL_ROLE_PP_SIZE:-${role_pp_size}}"
      role_layer_partition="${PREFILL_ROLE_LAYER_PARTITION:-${role_layer_partition}}"
