      role_layer_partition="${DECODE_ROLE_LAYER_PARTITION:-${role_layer_partition}}"
      ;;
  esac
  if [[ "${role}" == "proxy" ]]; then
    patch_proxy_native_routes "${host}" "${container}"
  else
    patch_vllm_core_runtime "${host}" "${container}"
    cleanup_role_start_residue "${host}" "${container}" "${role}" "${rank}"
