    -e TASK_ROOT=\"${TASK_ROOT}\" \
    -e TASK_ROOT_IN_CONTAINER=\"${TASK_ROOT_IN_CONTAINER}\" \
    -e CONTAINER_INSTALL_ROOT=\"${CONTAINER_INSTALL_ROOT}\" \
