wait_http() {
  local host="$1" url="$2" label="$3" timeout="${4:-7200}"
  local i failure_file
  failure_file="/tmp/fp8_v7_wait_http_failure_${TS}_${label}.txt"
  for ((i = 1; i <= timeout; i++)); do
    if remote "${host}" "curl -fsS --max-time 3 ${url} >/dev/null 2>&1"; then
      return 0
    fi
    if grep -R -m1 -E "Traceback|ValidationError|Value error|ValueError:|RuntimeError:|EngineCore failed to start|WorkerProc failed|CUDA error:|does not recognize this architecture" \
      "${LOG_DIR}/${TS}_${label}_rank"*.log > "${failure_file}" 2>/dev/null; then
      echo "failed waiting ${label} ${url}: $(cat "${failure_file}")" >&2
      return 1
    fi
    if ((i % 30 == 0)); then
      echo "$(date -u +%FT%TZ) waiting ${label} ${url} ${i}/${timeout}" >&2
    fi
    sleep 1
  done
  echo "timeout waiting ${label} ${url}" >&2
  return 1
}

collect_status() {
  for item in "${PREFILL0_HEAD}:${PREFILL_HEAD_CONTAINER}" "${PREFILL0_WORKER}:${PREFILL_WORKER_CONTAINER}" "${PREFILL1_HEAD}:${PREFILL1_HEAD_CONTAINER}" "${PREFILL1_WORKER}:${PREFILL1_WORKER_CONTAINER}" "${DECODE_HEAD}:${DECODE_HEAD_CONTAINER}" "${DECODE_WORKER}:${DECODE_WORKER_CONTAINER}"; do
    host="${item%%:*}"; cont="${item##*:}"
    remote "${host}" "bash -lc 'echo host=${host}; docker ps --filter name=${cont} --format \"container={{.Names}} status={{.Status}}\"; docker exec ${cont} bash -lc \"pgrep -af \\\"vllm.entrypoints.cli.main serve|[t]oy_proxy_server.py\\\" || true\"; nvidia-smi --query-gpu=index,memory.used --format=csv,noheader'" > "${LOG_DIR}/${TS}_${host}_status.txt" || true
  done
}

