up() {
  record deploy_start RUNNING "starting containers and formal 6-server 2P1D stack"
  stop_non_task_gpu_containers_if_needed "${PREFILL0_HEAD}"
  stop_non_task_gpu_containers_if_needed "${PREFILL0_WORKER}"
  stop_non_task_gpu_containers_if_needed "${PREFILL1_HEAD}"
  stop_non_task_gpu_containers_if_needed "${PREFILL1_WORKER}"
  stop_non_task_gpu_containers_if_needed "${DECODE_HEAD}"
  stop_non_task_gpu_containers_if_needed "${DECODE_WORKER}"
  ensure_container "${PREFILL0_HEAD}" "${PREFILL_HEAD_CONTAINER}"
  ensure_container "${PREFILL0_WORKER}" "${PREFILL_WORKER_CONTAINER}"
  ensure_container "${PREFILL1_HEAD}" "${PREFILL1_HEAD_CONTAINER}"
  ensure_container "${PREFILL1_WORKER}" "${PREFILL1_WORKER_CONTAINER}"
  ensure_container "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  ensure_container "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  stop_task_processes "${PREFILL0_HEAD}" "${PREFILL_HEAD_CONTAINER}"
  stop_task_processes "${PREFILL0_WORKER}" "${PREFILL_WORKER_CONTAINER}"
  stop_task_processes "${PREFILL1_HEAD}" "${PREFILL1_HEAD_CONTAINER}"
  stop_task_processes "${PREFILL1_WORKER}" "${PREFILL1_WORKER_CONTAINER}"
  stop_task_processes "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  stop_task_processes "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  wait_all_task_gpu_memory_released "pre_up"
  restart_container_clean "${PREFILL0_HEAD}" "${PREFILL_HEAD_CONTAINER}"
  restart_container_clean "${PREFILL0_WORKER}" "${PREFILL_WORKER_CONTAINER}"
  restart_container_clean "${PREFILL1_HEAD}" "${PREFILL1_HEAD_CONTAINER}"
  restart_container_clean "${PREFILL1_WORKER}" "${PREFILL1_WORKER_CONTAINER}"
  restart_container_clean "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  restart_container_clean "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  PREFILL_HEAD="${PREFILL0_HEAD}" PREFILL_WORKER="${PREFILL0_WORKER}" PREFILL_ENGINE_ID="${PREFILL0_ENGINE_ID:-fp8-2p1d-p0-prefill}" ROLE_LOG_SUFFIX=p0 start_role "${PREFILL0_WORKER}" "${PREFILL_WORKER_CONTAINER}" prefill 1
  sleep 5
  PREFILL_HEAD="${PREFILL0_HEAD}" PREFILL_WORKER="${PREFILL0_WORKER}" PREFILL_ENGINE_ID="${PREFILL0_ENGINE_ID:-fp8-2p1d-p0-prefill}" ROLE_LOG_SUFFIX=p0 start_role "${PREFILL0_HEAD}" "${PREFILL_HEAD_CONTAINER}" prefill 0
  wait_http "${PREFILL0_HEAD}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" prefill_p0 "${SERVICE_WAIT_TIMEOUT}"
  PREFILL_HEAD="${PREFILL1_HEAD}" PREFILL_WORKER="${PREFILL1_WORKER}" PREFILL_ENGINE_ID="${PREFILL1_ENGINE_ID:-fp8-2p1d-p1-prefill}" ROLE_LOG_SUFFIX=p1 start_role "${PREFILL1_WORKER}" "${PREFILL1_WORKER_CONTAINER}" prefill 1
  sleep 5
  PREFILL_HEAD="${PREFILL1_HEAD}" PREFILL_WORKER="${PREFILL1_WORKER}" PREFILL_ENGINE_ID="${PREFILL1_ENGINE_ID:-fp8-2p1d-p1-prefill}" ROLE_LOG_SUFFIX=p1 start_role "${PREFILL1_HEAD}" "${PREFILL1_HEAD_CONTAINER}" prefill 0
  wait_http "${PREFILL1_HEAD}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" prefill_p1 "${SERVICE_WAIT_TIMEOUT}"
  ROLE_LOG_SUFFIX=d0 start_role "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}" decode 1
  sleep 5
  ROLE_LOG_SUFFIX=d0 start_role "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}" decode 0
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${DECODE_PORT}/v1/models" decode_d0 "${SERVICE_WAIT_TIMEOUT}"
  PREFILL_HOSTS="${PREFILL0_HEAD} ${PREFILL1_HEAD}" PREFILL_PORTS="${PREFILL_PORT} ${PREFILL_PORT}" DECODE_HOSTS="${DECODE_HEAD}" DECODE_PORTS="${DECODE_PORT}" start_role "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}" proxy 0
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${PROXY_PORT}/healthcheck" proxy 600
  python3 - "${TASK_ROOT}/state/watchdog/prefill_status.json" "${PREFILL0_HEAD}" "${PREFILL_PORT}" "${PREFILL1_HEAD}" "${PREFILL_PORT}" <<'PY'
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

path = Path(sys.argv[1])
p0_host, p0_port, p1_host, p1_port = sys.argv[2:6]
now = datetime.now(timezone.utc).isoformat()
prefills = {}
for host, port in ((p0_host, p0_port), (p1_host, p1_port)):
    for key in (f"{host}:{port}", host):
        prefills[key] = {
            "status": "healthy",
            "error_code": "",
            "reason": "deploy proxy ready",
            "updated_at": now,
            "source": "deploy",
        }
data = {"updated_at": now, "source": "deploy", "prefills": prefills}
path.parent.mkdir(parents=True, exist_ok=True)
tmp = path.with_suffix(path.suffix + ".tmp")
tmp.write_text(json.dumps(data, ensure_ascii=False, sort_keys=True) + "\n", encoding="utf-8")
tmp.replace(path)
PY
  collect_status
  write_manifest
  record deploy_ready PASS "endpoint=http://${DECODE_HEAD}:${PROXY_PORT}/v1 manifest=${MANIFEST_REL}"
  echo "endpoint=http://${DECODE_HEAD}:${PROXY_PORT}/v1"
}

