  stop_non_task_gpu_containers_if_needed "${DECODE_WORKER}"
  ensure_container "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  ensure_container "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  stop_task_processes "${PREFILL_HEAD}" "${PREFILL_HEAD_CONTAINER}"
  stop_task_processes "${PREFILL_WORKER}" "${PREFILL_WORKER_CONTAINER}"
  stop_task_processes "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  stop_task_processes "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  restart_container_clean "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  restart_container_clean "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  start_role "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}" nonpd 1
  sleep 5
  start_role "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}" nonpd 0
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${DECODE_PORT}/v1/models" nonpd "${SERVICE_WAIT_TIMEOUT}"
  collect_status
  write_manifest
  record deploy_ready PASS "endpoint=http://${DECODE_HEAD}:${DECODE_PORT}/v1 manifest=${MANIFEST_REL}"
  echo "endpoint=http://${DECODE_HEAD}:${DECODE_PORT}/v1"
}

resume_decode_after_prefill() {
  record deploy_resume RUNNING "waiting existing prefill and starting decode/proxy"
  ensure_container "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  ensure_container "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  wait_http "${PREFILL_HEAD}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" prefill "${SERVICE_WAIT_TIMEOUT}"
  stop_task_processes "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  stop_task_processes "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  restart_container_clean "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  restart_container_clean "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  start_role "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}" decode 1
  sleep 5
  start_role "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}" decode 0
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${DECODE_PORT}/v1/models" decode "${SERVICE_WAIT_TIMEOUT}"
  start_role "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}" proxy 0
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${PROXY_PORT}/healthcheck" proxy 600
  collect_status
  write_manifest
  record deploy_ready PASS "endpoint=http://${DECODE_HEAD}:${PROXY_PORT}/v1 manifest=${MANIFEST_REL}"
  echo "endpoint=http://${DECODE_HEAD}:${PROXY_PORT}/v1"
}

resume_p1_decode_after_p0() {
  record deploy_resume RUNNING "retaining healthy P0; starting P1, decode, and proxy"
  deploy_step "resume_p1_decode ensure containers"
  ensure_container "${PREFILL1_HEAD}" "${PREFILL1_HEAD_CONTAINER}"
  ensure_container "${PREFILL1_WORKER}" "${PREFILL1_WORKER_CONTAINER}"
  ensure_container "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  ensure_container "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
