restart_prefill_group_only() {
  local group="$1"
  local head worker head_container worker_container engine_id log_suffix other_head
  case "${group}" in
    P0|p0|0)
      group="P0"
      head="${PREFILL0_HEAD}"
      worker="${PREFILL0_WORKER}"
      head_container="${PREFILL_HEAD_CONTAINER}"
      worker_container="${PREFILL_WORKER_CONTAINER}"
      engine_id="${PREFILL0_ENGINE_ID:-fp8-2p1d-p0-prefill}"
      log_suffix="p0"
      other_head="${PREFILL1_HEAD}"
      ;;
    P1|p1|1)
      group="P1"
      head="${PREFILL1_HEAD}"
      worker="${PREFILL1_WORKER}"
      head_container="${PREFILL1_HEAD_CONTAINER}"
      worker_container="${PREFILL1_WORKER_CONTAINER}"
      engine_id="${PREFILL1_ENGINE_ID:-fp8-2p1d-p1-prefill}"
      log_suffix="p1"
      other_head="${PREFILL0_HEAD}"
      ;;
    *)
      echo "unknown prefill group: ${group}" >&2
      return 2
      ;;
  esac

  record "deploy_${group}_restart" RUNNING "restarting ${group} only; the other Prefill, Decode, and Proxy are retained"
  deploy_step "restart_${group} verify retained path"
  wait_http "${other_head}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" "retained_prefill_${group}" 30
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${DECODE_PORT}/v1/models" "retained_decode_${group}" 30
  ensure_container "${head}" "${head_container}"
  ensure_container "${worker}" "${worker_container}"
  deploy_step "restart_${group} stop old task processes"
  stop_task_processes "${head}" "${head_container}"
  stop_task_processes "${worker}" "${worker_container}"
  deploy_step "restart_${group} restart containers"
  restart_container_clean "${head}" "${head_container}"
  restart_container_clean "${worker}" "${worker_container}"
  deploy_step "restart_${group} start worker"
  PREFILL_HEAD="${head}" PREFILL_WORKER="${worker}" PREFILL_ENGINE_ID="${engine_id}" ROLE_LOG_SUFFIX="${log_suffix}" start_role "${worker}" "${worker_container}" prefill 1
  sleep 5
  deploy_step "restart_${group} start head"
  PREFILL_HEAD="${head}" PREFILL_WORKER="${worker}" PREFILL_ENGINE_ID="${engine_id}" ROLE_LOG_SUFFIX="${log_suffix}" start_role "${head}" "${head_container}" prefill 0
  deploy_step "restart_${group} wait models"
  wait_http "${head}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" "prefill_${group}" "${SERVICE_WAIT_TIMEOUT}"
  collect_status
  write_manifest
  record "deploy_${group}_restart" PASS "prefill=${head}:${PREFILL_PORT} manifest=${MANIFEST_REL}; retained_other_prefill=${other_head}:${PREFILL_PORT} retained_decode=${DECODE_HEAD}:${DECODE_PORT}"
  echo "prefill_endpoint=http://${head}:${PREFILL_PORT}/v1"
}

restart_proxy_only() {
  record deploy_proxy_restart RUNNING "restarting proxy only; P0/P1/D0 vLLM processes retained"
  ensure_container "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  wait_http "${PREFILL0_HEAD}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" prefill_p0 "${SERVICE_WAIT_TIMEOUT}"
  wait_http "${PREFILL1_HEAD}" "http://127.0.0.1:${PREFILL_PORT}/v1/models" prefill_p1 "${SERVICE_WAIT_TIMEOUT}"
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${DECODE_PORT}/v1/models" decode_d0 "${SERVICE_WAIT_TIMEOUT}"
  stop_proxy_process "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  PREFILL_HOSTS="${PREFILL0_HEAD} ${PREFILL1_HEAD}" PREFILL_PORTS="${PREFILL_PORT} ${PREFILL_PORT}" DECODE_HOSTS="${DECODE_HEAD}" DECODE_PORTS="${DECODE_PORT}" start_role "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}" proxy 0
  wait_http "${DECODE_HEAD}" "http://127.0.0.1:${PROXY_PORT}/healthcheck" proxy 600
  collect_status
  write_manifest
  record deploy_proxy_restart PASS "endpoint=http://${DECODE_HEAD}:${PROXY_PORT}/v1 manifest=${MANIFEST_REL}"
  echo "endpoint=http://${DECODE_HEAD}:${PROXY_PORT}/v1"
}

down() {
  stop_task_processes "${PREFILL0_HEAD}" "${PREFILL_HEAD_CONTAINER}"
  stop_task_processes "${PREFILL0_WORKER}" "${PREFILL_WORKER_CONTAINER}"
  stop_task_processes "${PREFILL1_HEAD}" "${PREFILL1_HEAD_CONTAINER}"
  stop_task_processes "${PREFILL1_WORKER}" "${PREFILL1_WORKER_CONTAINER}"
  stop_task_processes "${DECODE_HEAD}" "${DECODE_HEAD_CONTAINER}"
  stop_task_processes "${DECODE_WORKER}" "${DECODE_WORKER_CONTAINER}"
  wait_all_task_gpu_memory_released "down"
  record deploy_stop PASS "task service processes stopped; containers retained"
}

case "${ACTION}" in
  up) up ;;
  down) down ;;
  restart) down; up ;;
  proxy_restart) restart_proxy_only ;;
  restart_prefill0_only|restart_p0_only) restart_prefill_group_only P0 ;;
  restart_prefill1_only|restart_p1_only) restart_prefill_group_only P1 ;;
  resume_decode) resume_decode_after_prefill ;;
  resume_p1_decode) resume_p1_decode_after_p0 ;;
  resume_p1_decode_no_restart) resume_p1_decode_after_p0_no_restart ;;
  nonpd_restart) down; up_nonpd ;;
  status) collect_status; record deploy_status PASS "status collected under ${LOG_DIR}" ;;
  *) echo "usage: $0 up|down|restart|proxy_restart|restart_prefill0_only|restart_prefill1_only|resume_decode|resume_p1_decode|nonpd_restart|status [scheme]" >&2; exit 2 ;;
esac
